{
  func main<ios18>(tensor<fp16, [1, 16, 50, 1]> x, tensor<fp16, [1, 16, 50, 1]> scale, tensor<fp16, [1, 1, 50, 1]> mask) {
    tensor<fp16, [1, 16, 50, 1]> scaled = mul(x = x, y = scale)[name = string("scaled")];
    tensor<fp16, [1, 16, 50, 1]> masked = add(x = scaled, y = mask)[name = string("masked")];
    tensor<fp16, [1, 16, 50, 1]> y = softmax(axis = 3, x = masked)[name = string("y")];
  } -> (y);
}
